page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Focused hand jump review</title><style>
:root{color-scheme:dark;font-family:system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:#10141c;color:#edf1f7;line-height:1.5}main{max-width:1320px;margin:auto;padding:24px}a{color:#91bdff}h1{margin:0 0 12px;font-size:30px}h2{margin:0;font-size:20px}p{max-width:1050px;color:#bdc8d8}nav{display:flex;gap:20px;flex-wrap:wrap;margin:16px 0 24px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.card{border:1px solid #3d4b62;border-radius:12px;background:#18212f;padding:18px}.tag{display:inline-block;background:#5a4520;color:#ffe6a3;border-radius:20px;padding:3px 10px;font-size:12px;margin:10px 0}.screen{height:528px;display:flex;justify-content:center;background:#080c13;border-radius:8px;overflow:hidden}video{height:100%;max-width:100%;object-fit:contain}.controls{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:12px 0}button,select{font:inherit;color:inherit;background:#26364e;border:1px solid #536582;border-radius:6px;padding:7px 10px;cursor:pointer}button:disabled{opacity:.45;cursor:wait}label{white-space:nowrap}input[type=range]{width:100%;accent-color:#78aaff}.clock{font-variant-numeric:tabular-nums;min-height:27px;color:#dbe6f5}.at-event{color:#ffd37a;font-weight:650}.meta{font-size:13px;color:#acbbce}.evidence{display:flex;gap:12px;flex-wrap:wrap;font-size:13px;margin-top:12px}.note{font-size:14px}.error{color:#ffb4a8}summary{cursor:pointer;color:#c5d7ed}details{margin-top:12px}@media(max-width:800px){main{padding:16px}.grid{grid-template-columns:1fr}.screen{height:min(528px,115vw)}}
</style></head><body><main><h1>Focused hand jump review</h1><p>Four <strong>unconfirmed candidates</strong> from saved generations. Each clip includes two seconds before and after the marked frame. Start immediately before the candidate, then step forward one frame or play slowly. Toggle the pose overlay to compare the hand itself.</p><p>These videos were rerendered locally from the saved poses and original actor references. They are not pixel-identical crops of previously rendered full-minute videos.</p><nav><a href="../hand-review/index.html">All hand candidates</a><a href="../index.html">Audit overview</a><a href="verification.json">Media verification</a></nav><div class="grid" id="cards"></div></main><script>
const DATA=__DATA__;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let active=null;
for(const r of DATA.records){const card=document.createElement('article');card.className='card';card.id=r.id;card.innerHTML=`<h2>${esc(r.title)}</h2><div class="meta">${esc(r.run_id)} · source frame ${r.frame} · ${r.time_s.toFixed(2)}s</div><span class="tag">Unconfirmed candidate</span><div class="screen"><video controls playsinline muted preload="auto" poster="${esc(r.base)}/overlay.jpg"></video></div><div class="clock" aria-live="polite">Loading video…</div><div class="controls"><button data-play disabled>Play slowly</button><label>Speed <select data-speed><option value="0.1">0.1×</option><option value="0.25">0.25×</option><option value="0.5">0.5×</option><option value="1">1×</option></select></label><label><input data-overlay type="checkbox" checked> Pose overlay</label></div><div class="controls"><button data-step="-1" disabled>← Frame</button><button data-step="1" disabled>Frame →</button><button data-before disabled>Before candidate</button><button data-event disabled>Candidate frame</button></div><input data-slider type="range" min="0" max="99" value="49" aria-label="Video frame" disabled><div class="error" role="status"></div><details><summary>Independent visual review</summary><p class="note">${esc(r.note)} This is a review observation, not a user-confirmed label.</p></details><div class="evidence"><a href="${esc(r.base)}/overlay.mp4">Download overlay</a><a href="${esc(r.base)}/video.mp4">Download video</a><a href="${esc(r.base)}/overlay-boundary-contact.png">Boundary frames</a><a href="${esc(r.base)}/pose-contact.png">Pose trajectory</a><a href="${esc(r.base)}/visual-review.json">Review record</a></div>`;document.getElementById('cards').append(card);
const v=card.querySelector('video'),clock=card.querySelector('.clock'),slider=card.querySelector('[data-slider]'),play=card.querySelector('[data-play]'),speed=card.querySelector('[data-speed]'),overlay=card.querySelector('[data-overlay]'),error=card.querySelector('.error');let index=49,ready=false,resumeAfterLoad=false;
function describe(){const f=r.start_frame+index;clock.textContent=`Source frame ${f} · ${(f/r.fps).toFixed(2)}s · ${f===r.frame?'CANDIDATE FRAME':f===r.frame-1?'Immediately before candidate':f<r.frame?'Before candidate':'After candidate'}`;clock.classList.toggle('at-event',f===r.frame);slider.value=index;card.dataset.frame=String(f);}
function seek(i){v.pause();index=Math.max(0,Math.min(r.frames-1,i));v.currentTime=(index+.1)/r.fps;describe();}
function fromTime(t){if(!ready||v.seeking)return;index=Math.max(0,Math.min(r.frames-1,Math.floor(t*r.fps+1e-5)));describe();}
function load(){ready=false;for(const b of card.querySelectorAll('button,[data-slider]'))b.disabled=true;error.textContent='';v.src=r.base+'/'+(overlay.checked?'overlay.mp4':'video.mp4');v.load();}
v.addEventListener('loadedmetadata',()=>{v.playbackRate=+speed.value;seek(index);ready=true;for(const b of card.querySelectorAll('button,[data-slider]'))b.disabled=false;if(resumeAfterLoad){resumeAfterLoad=false;v.play().catch(e=>error.textContent=e.message);}});
v.addEventListener('play',()=>{if(active&&active!==v)active.pause();active=v;play.textContent='Pause';});v.addEventListener('pause',()=>play.textContent='Play slowly');v.addEventListener('timeupdate',()=>fromTime(v.currentTime));v.addEventListener('seeked',()=>fromTime(v.currentTime));v.addEventListener('error',()=>{error.textContent='Video could not load. The download links remain available.';});
if(v.requestVideoFrameCallback){const cb=(now,meta)=>{fromTime(meta.mediaTime);v.requestVideoFrameCallback(cb);};v.requestVideoFrameCallback(cb);}
play.onclick=()=>{if(!v.paused){v.pause();return;}if(index>=r.frames-1)seek(0);v.playbackRate=+speed.value;v.play().catch(e=>error.textContent=e.message);};speed.onchange=()=>v.playbackRate=+speed.value;overlay.onchange=()=>{resumeAfterLoad=!v.paused;load();};for(const b of card.querySelectorAll('[data-step]'))b.onclick=()=>seek(index+Number(b.dataset.step));card.querySelector('[data-before]').onclick=()=>seek(r.candidate_clip_frame-1);card.querySelector('[data-event]').onclick=()=>seek(r.candidate_clip_frame);slider.oninput=()=>seek(+slider.value);load();}
</script></body></html>'''
